<script setup>
import { ref,reactive,computed,onMounted } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { notify } from '../../services/notifications.js';
import { fetchAll,idOf } from '../../services/panel.js';
import { loadStores } from '../../services/workspace.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),users=ref([]),loading=ref(true),saving=ref(false),error=ref('');
const form=reactive({ownerId:'',name:'',slug:'',description:'',active:false});
onMounted(async()=>{try{users.value=(await fetchAll('/admin/users')).filter(u=>u.role==='vendedor');if(editing.value){const store=await api.get(`/admin/stores/${route.params.id}`);Object.assign(form,{ownerId:idOf(store.ownerId),name:store.name,slug:store.slug,description:store.description||'',active:store.active})}}catch(e){error.value=e.message}finally{loading.value=false}});
function suggestSlug(){if(editing.value||form.slug)return;form.slug=form.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
async function save(){saving.value=true;error.value='';try{if(editing.value)await api.put(`/admin/stores/${route.params.id}`,form);else await api.post('/admin/stores',form);await loadStores();notify.success(editing.value?'Tienda actualizada.':'Tienda creada. Ya podés personalizarla.');router.push('/app/stores')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><RouterLink to="/app/stores" class="p-back-link"><Icon name="back" :size="14"/>Volver a tiendas</RouterLink><header class="p-page-header"><div><h1>{{editing?'Editar tienda':'Una nueva tienda, una nueva historia.'}}</h1><p>Elegí el vendedor y la identidad inicial del negocio.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else class="p-form" @submit.prevent="save"><section class="p-section-card"><div class="p-section-title"><div><h2>Datos de la tienda</h2><p>La dirección identifica públicamente a la tienda.</p></div><Icon name="store"/></div><div class="p-form-grid"><div class="p-field full"><label for="store-owner">Vendedor responsable <span class="required">*</span></label><select id="store-owner" v-model="form.ownerId" required><option disabled value="">Seleccionar vendedor</option><option v-for="user in users" :key="user._id" :value="user._id">{{user.name}} · {{user.email}}{{!user.active?' (desactivado)':''}}</option></select><small>Se aplica el límite de tiendas de su plan. <RouterLink v-if="!users.length" to="/app/users/new">Crear un vendedor</RouterLink></small></div><div class="p-field"><label for="store-name">Nombre <span class="required">*</span></label><input id="store-name" v-model.trim="form.name" required maxlength="100" @blur="suggestSlug"/></div><div class="p-field"><label for="store-slug">Dirección /t/ <span class="required">*</span></label><input id="store-slug" v-model.trim="form.slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" minlength="3" maxlength="80" placeholder="mi-emprendimiento"/><small>Usá letras minúsculas, números y guiones. Cambiarla modifica el enlace público.</small></div><div class="p-field full"><label for="store-description">Descripción</label><textarea id="store-description" v-model="form.description" maxlength="2000" rows="3"/></div><div class="p-field full"><label class="p-check"><input v-model="form.active" type="checkbox"/>Publicar tienda</label><small>La tienda solo puede estar pública si el vendedor tiene un plan o una prueba vigente.</small></div></div></section><footer class="p-form-footer"><small>Podés modificar el diseño después de crearla.</small><div class="p-form-actions"><RouterLink to="/app/stores" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':editing?'Guardar cambios':'Crear tienda'}}</button></div></footer></form></div></template>
